package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"runtime"
	"sync"
)

// Request 模拟业务请求体
type Request struct {
	ID      int    `json:"id"`
	Payload string `json:"payload"`
}

// bufPool 复用 bytes.Buffer，显著减少堆分配
var bufPool = sync.Pool{
	New: func() any {
		return new(bytes.Buffer)
	},
}

// EncodeWithPool 使用对象池完成 JSON 编码
func EncodeWithPool(req *Request) ([]byte, error) {
	buf := bufPool.Get().(*bytes.Buffer) // 1. 从池中取出（可能触发 New）
	buf.Reset()                          // 2. 复用前必须重置，防止脏数据

	if err := json.NewEncoder(buf).Encode(req); err != nil {
		bufPool.Put(buf) // 异常路径也要归还，避免对象泄漏
		return nil, err
	}

	out := make([]byte, buf.Len())
	copy(out, buf.Bytes()) // 3. 必须拷贝结果，buffer 即将被他人复用
	bufPool.Put(buf)       // 4. 归还对象供下一次复用
	return out, nil
}

// EncodeNoPool 对照组：每次调用都新建 buffer
func EncodeNoPool(req *Request) ([]byte, error) {
	var buf bytes.Buffer
	if err := json.NewEncoder(&buf).Encode(req); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// measureAllocs 粗略统计单次调用平均堆分配字节数
func measureAllocs(f func(), n int) float64 {
	var m1, m2 runtime.MemStats
	runtime.GC()
	runtime.ReadMemStats(&m1)
	for i := 0; i < n; i++ {
		f()
	}
	runtime.ReadMemStats(&m2)
	return float64(m2.TotalAlloc-m1.TotalAlloc) / float64(n)
}

func main() {
	req := &Request{ID: 1001, Payload: "hello sync.Pool"}

	b, err := EncodeWithPool(req)
	if err != nil {
		panic(err)
	}
	fmt.Printf("encoded: %s", b)

	const n = 100000
	fmt.Printf("with pool:    %.0f bytes/op\n", measureAllocs(func() { _, _ = EncodeWithPool(req) }, n))
	fmt.Printf("without pool: %.0f bytes/op\n", measureAllocs(func() { _, _ = EncodeNoPool(req) }, n))

	runtime.GC()
	fmt.Println("注意：GC 之后 Pool 中的对象可能被清理，New 会被再次调用")
}

